<?php
declare(strict_types=1);
require_once __DIR__.'/CommerceScheduleService.php';
/** Calendar and allocation review UI; all database writes stay in shared services. */
final class CommercePlanningExperience
{
    private static function e(mixed $v):string{return CommerceExperience::e($v);}
    private static function rows(PDO $db,string $sql,array $args=[]):array{$q=$db->prepare($sql);$q->execute($args);return$q->fetchAll();}
    public static function handles(string $action):bool{return in_array($action,['schedule_review','schedule_apply','allocation_review','allocation_apply','showtime_change','legacy_showtime','venue_timezone'],true);}
    private static function store(int $org,array $u,array $review):string
    {
        $key=bin2hex(random_bytes(16));$_SESSION['commerce_planning']??=[];if(count($_SESSION['commerce_planning'])>=20)array_shift($_SESSION['commerce_planning']);$_SESSION['commerce_planning'][$key]=$review+['org'=>$org,'actor'=>(int)$u['id'],'created'=>time()];return$key;
    }
    private static function review(int $org,array $u,string $key,string $type):array
    {
        $r=$_SESSION['commerce_planning'][$key]??null;if(!$r||$r['org']!==$org||$r['actor']!==(int)$u['id']||$r['type']!==$type||$r['created']<time()-1200)throw new RuntimeException('This review expired. Start a new preview.');return$r;
    }
    public static function command(PDO $db,array $u,int $org,string $action):string
    {
        CommerceAccess::demand($db,$u,$org,$action==='venue_timezone'?'venues':'inventory');$id=(int)($_POST['id']??0);
        if($action==='schedule_review'){$production=(int)($_POST['production']??0);$layout=(int)($_POST['layout']??0);$prices=($_POST['pricing_source']??'')==='production'?(CommercePricingService::defaults($db,$org,$production)['prices']??throw new RuntimeException('Set production default pricing first.')):(isset($_POST['price_rows'])?CommercePricingService::parse((array)$_POST['price_rows']):json_decode((string)($_POST['prices']??''),true,512,JSON_THROW_ON_ERROR));if(!is_array($prices))throw new RuntimeException('Enter a valid pricing document.');$input=array_intersect_key($_POST,array_flip(['dates','times','offsets','weekly_enabled','range_start','range_end','weekly','exceptions','dst_choice','seating_mode','pricing_source','drawer','initial_sales','fee_amount','tax_percent','discount_amount']));$ambiguous=[];
            if(!empty($input['drawer'])){
                $zone=CommercePerformancePolicy::venueTimezone($db,$org,$layout);$layoutRow=CommerceStore::row($db,'layouts',$org,$layout);$zones=[];foreach(json_decode($layoutRow['document_json'],true)['items'] as $seat)if($seat['kind']==='seat')$zones[]=(string)$seat['zone'];
                if(($input['pricing_source']??'')!=='production')foreach(array_keys($prices) as $priceZone)if(!in_array((string)$priceZone,$zones,true))throw new RuntimeException('Choose pricing zones from the selected seating layout.');
                foreach((array)($input['dates']??[]) as $i=>$date){$time=(string)($input['times'][$i]??'');if($date===''&&$time==='')continue;try{CommercePerformancePolicy::resolve($date.'T'.$time,$zone);}catch(RuntimeException $e){if(!str_contains($e->getMessage(),'occurs twice'))throw $e;$ambiguous[]=$i;}}
                foreach($ambiguous as $i)if(empty($input['offsets'][$i])&&empty($input['dst_choice'])){$key=self::store($org,$u,compact('production','layout','prices','input','ambiguous')+['type'=>'schedule_ambiguity']);return CommerceExperience::url('add_performance',['production'=>$production,'draft'=>$key]);}
            }
            $preview=CommerceScheduleService::preview($db,$u,$org,$production,$layout,$prices,$input);$key=self::store($org,$u,compact('production','layout','prices','input','preview','ambiguous')+['type'=>'schedule']);return CommerceExperience::url('schedule',['review'=>$key]);}
        if($action==='schedule_apply'){$r=self::review($org,$u,(string)($_POST['review_key']??''),'schedule');$ids=CommerceScheduleService::create($db,$u,$org,$r['production'],$r['layout'],$r['prices'],$r['input'],$r['preview']['hash'],(string)$_POST['review_key']);$_SESSION['commerce_notice']='Created '.count($ids).' performances with sales '.(($r['input']['initial_sales']??'closed')==='open'?'open':'closed').'. The reviewed ticket fees and taxes were applied.';return CommerceExperience::url('performances');}
        if($action==='allocation_review'){$scope=['production'=>(int)($_POST['production']??0),'mode'=>(string)($_POST['scope']??'selected'),'ids'=>(array)($_POST['performances']??[]),'from'=>(string)($_POST['from']??''),'to'=>(string)($_POST['to']??'')];$ids=CommerceInventoryService::allocationScope($db,$u,$org,$scope);$seats=(array)($_POST['seats']??[]);$state=(string)($_POST['state']??'');$reason=(string)($_POST['reason']??'');$preview=CommerceInventoryService::allocationPreview($db,$u,$org,$ids,$seats,$state,$reason);$key=self::store($org,$u,compact('scope','ids','seats','state','reason','preview')+['type'=>'allocation']);return CommerceExperience::url('blocks',['review'=>$key]);}
        if($action==='allocation_apply'){$r=self::review($org,$u,(string)($_POST['review_key']??''),'allocation');try{$result=CommerceInventoryService::allocateMany($db,$u,$org,$r['ids'],$r['seats'],$r['state'],$r['reason'],$r['preview']['hash'],(string)$_POST['review_key'],$r['scope']);}catch(RuntimeException $e){if(str_contains($e->getMessage(),'Performance #'))throw new RuntimeException('Some selected seats are no longer available. Review the affected performances and seats again.');throw $e;}$_SESSION['commerce_notice']=self::actionLabel($result['state']).' applied to '.$result['affected'].' seats or tickets across '.count($result['performances']).' performances.';return CommerceExperience::url('blocks',['production'=>$r['scope']['production']]);}
        if($action==='venue_timezone'){CommerceScheduleService::venueTimezone($db,$u,$org,$id,(string)($_POST['timezone']??''));return CommerceExperience::url('venues');}
        try{
            if($action==='legacy_showtime')CommerceScheduleService::reviewLegacy($db,$u,$org,$id,(string)($_POST['timezone']??''),(string)($_POST['offset']??''),(string)($_POST['reason']??''));
            else CommerceScheduleService::change($db,$u,$org,$id,(string)($_POST['starts']??''),(string)($_POST['offset']??''),(string)($_POST['status']??''),(string)($_POST['reason']??''),(string)($_POST['version']??''),!empty($_POST['acknowledge_paid']));
        }catch(RuntimeException $e){
            if(!str_contains($e->getMessage(),'occurs twice'))throw $e;
            $key=self::store($org,$u,['type'=>'showtime_ambiguity','performance'=>$id,'input'=>array_intersect_key($_POST,array_flip(['starts','status','reason','version','acknowledge_paid','timezone']))]);
            return CommerceExperience::url('performance',['id'=>$id,'showtime_review'=>$key]);
        }
        return CommerceExperience::url('performance',['id'=>$id]);
    }
    private static function productionSelect(PDO $db,int $selected):void
    {
        echo '<label>Production<select name="production" required><option value="">Choose a production</option>';foreach(self::rows($db,"SELECT id,title FROM productions WHERE lifecycle_stage IN ('upcoming','planning','in_production','performing') ORDER BY title") as $p)echo '<option value="'.(int)$p['id'].'" '.($selected===(int)$p['id']?'selected':'').'>'.self::e($p['title']).'</option>';echo '</select></label>';
    }
    public static function schedule(PDO $db,array $u,int $org):void
    {
        CommerceAccess::demand($db,$u,$org,'inventory');if(isset($_GET['review'])){echo '<div data-production-drawer>';self::scheduleReview($db,$u,$org,(string)$_GET['review']);echo '</div>';return;}$production=(int)($_GET['production']??0);$next=self::rows($db,'SELECT production_id,starts_at FROM commerce_performances WHERE organization_id=? AND starts_at>=? ORDER BY starts_at LIMIT 1',[$org,date('Y-m-d H:i:s')]);if(!$production&&!isset($_GET['production'])&&$next)$production=(int)$next[0]['production_id'];$month=(string)($_GET['month']??($next&&(int)$next[0]['production_id']===$production?substr($next[0]['starts_at'],0,7):date('Y-m')));if(!preg_match('/^\d{4}-(?:0[1-9]|1[0-2])$/',$month))$month=date('Y-m');echo '<h2>Performance schedule</h2><p>Select exact showtimes or build a weekly template, then review every date before creating inventory. Selecting a calendar day alone does not create a performance.</p><form method="get"><input type="hidden" name="tab" value="schedule">';self::productionSelect($db,$production);CommerceExperience::input('month','Calendar month','month',$month,'required');echo '<button>View calendar</button></form>';if(!$production)return;
        $performances=self::rows($db,'SELECT * FROM commerce_performances WHERE organization_id=? AND production_id=? ORDER BY starts_at',[$org,$production]);$byDate=[];foreach($performances as $p)$byDate[substr($p['starts_at'],0,10)][]=$p;$first=new DateTimeImmutable($month.'-01');echo '<div class="commerce-calendar" aria-label="'.self::e($first->format('F Y')).' performance calendar">';foreach(['Mon','Tue','Wed','Thu','Fri','Sat','Sun'] as $day)echo '<strong aria-hidden="true">'.$day.'</strong>';for($i=1;$i<(int)$first->format('N');$i++)echo '<span></span>';for($day=1;$day<=(int)$first->format('t');$day++){$date=$month.'-'.sprintf('%02d',$day);echo '<div class="commerce-calendar-day"><button type="button" data-calendar-date="'.$date.'" aria-label="Select '.$date.'">'.$day.'</button>';foreach($byDate[$date]??[] as $p)echo '<a href="'.self::e(CommerceExperience::url('performance',['id'=>$p['id']])).'">'.self::e(substr($p['starts_at'],11,5).' · '.$p['schedule_status']).'</a>';echo '</div>';}echo '</div>';
        CommerceExperience::form('schedule_review',['production'=>$production]);echo '<label>Published venue / layout<select name="layout" required><option value="">Choose layout</option>';foreach(self::rows($db,"SELECT l.id,l.version_number,s.name auditorium,v.name venue,v.timezone_name FROM commerce_layouts l JOIN commerce_spaces s ON s.id=l.space_id AND s.organization_id=l.organization_id JOIN commerce_venues v ON v.id=s.venue_id AND v.organization_id=s.organization_id WHERE l.organization_id=? AND l.status='published'",[$org]) as $l)echo '<option value="'.(int)$l['id'].'">'.self::e($l['venue'].' / '.$l['auditorium'].' · v'.$l['version_number'].' · '.($l['timezone_name']?:getenv('COMMERCE_VENUE_TIMEZONE')?:getenv('APP_TIMEZONE')?:'America/New_York')).'</option>';echo '</select></label><label>Seating mode<select name="seating_mode"><option value="reserved">Reserved seats</option><option value="general_admission">General admission (layout defines capacity)</option></select></label><h3>Individually selected showtimes</h3><p>Choose a day above or use each row’s date picker. Add separate rows for matinee and evening shows.</p><div data-showtime-rows>';self::showtimeRow();echo '</div><button type="button" data-add-showtime>Add another exact showtime</button><details><summary>Recurring schedule & exceptions</summary><fieldset><legend>Weekly template (optional)</legend><label><input type="checkbox" name="weekly_enabled" value="1"> Also generate these weekly showtimes</label><div class="commerce-columns">';CommerceExperience::input('range_start','Template start date','date');CommerceExperience::input('range_end','Template end date','date');echo '</div><p>Use 24-hour times separated by commas, for example 14:00, 19:00. Leave days without performances blank.</p><div class="commerce-columns">';foreach([1=>'Monday',2=>'Tuesday',3=>'Wednesday',4=>'Thursday',5=>'Friday',6=>'Saturday',7=>'Sunday'] as $n=>$day)CommerceExperience::input('weekly['.$n.']',$day.' times','text','','placeholder="HH:MM, HH:MM"');echo '</div></fieldset><label>Exceptions<textarea name="exceptions" rows="3" placeholder="YYYY-MM-DD or YYYY-MM-DDTHH:MM"></textarea></label><p>Separate exclusions with commas or new lines. A date removes every show that day; a date and time removes only that show.</p><label>Repeated daylight-saving hour<select name="dst_choice"><option value="">Require explicit resolution if a time occurs twice</option><option value="earlier">Use the first occurrence of a repeated hour</option><option value="later">Use the second occurrence of a repeated hour</option></select></label><p>Times skipped when clocks change are not available. Review each local performance time before saving.</p>';
        echo '</details>';$defaults=CommercePricingService::ready($db)?CommercePricingService::defaults($db,$org,$production):null;$prices=$defaults['prices']??($performances?json_decode($performances[count($performances)-1]['prices_json'],true):['standard'=>['Adult'=>null]]);echo '<label>Pricing source<select name="pricing_source" data-pricing-source><option value="production" '.($defaults?'selected':'disabled').'>Inherit production defaults</option><option value="override" '.(!$defaults?'selected':'').'>Performance override</option></select></label>';CommerceProductionExperience::priceEditor($prices);echo '<p>New performances start with closed sales, no fee, no tax and no discount. Configure those settings before opening sales.</p><button>Review exact performances</button></form>';
    }
    private static function showtimeRow():void
    {
        echo '<div class="commerce-showtime-row"><label>Exact date<input type="date" name="dates[]" data-exact-date></label><label>Local time<input type="time" name="times[]" step="60"></label><input type="hidden" name="offsets[]" value=""><button type="button" data-remove-showtime>Remove showtime</button></div>';
    }
    private static function scheduleReview(PDO $db,array $u,int $org,string $key):void
    {
        $r=self::review($org,$u,$key,'schedule');$preview=CommerceScheduleService::preview($db,$u,$org,$r['production'],$r['layout'],$r['prices'],$r['input']);$context=self::rows($db,'SELECT p.title,v.name venue,s.name auditorium FROM productions p JOIN commerce_layouts l ON l.id=? AND l.organization_id=? JOIN commerce_spaces s ON s.id=l.space_id AND s.organization_id=l.organization_id JOIN commerce_venues v ON v.id=s.venue_id AND v.organization_id=s.organization_id WHERE p.id=?',[$r['layout'],$org,$r['production']])[0];
        echo '<h2>Review Performances</h2><p>'.self::e($context['title']).'</p><p>'.self::e($context['venue'].' / '.$context['auditorium']).'</p><p>'.count($preview['times']).' performances · '.($preview['seating_mode']==='general_admission'?'General admission':'Reserved seating').'</p><p>Times shown in '.self::e($preview['timezone']).'.</p>';
        foreach($preview['conflicts'] as $conflict){$message=preg_replace(['/performance #\d+/i','/ [+-]\d{2}:\d{2}/'],['performance',''],$conflict);echo '<p role="alert">'.self::e(CommerceExperience::staffMessage($message)).'</p>';}
        echo '<div class="commerce-table-scroll"><table><caption>Performance dates and times</caption><thead><tr><th>Date</th><th>Time</th></tr></thead><tbody>';foreach($preview['times'] as $time){$local=new DateTimeImmutable($time['local'],new DateTimeZone($preview['timezone']));echo '<tr><td>'.self::e($local->format('l, F j, Y')).'</td><td>'.self::e($local->format('g:i A')).'</td></tr>';}echo '</tbody></table></div>';
        $layout=CommerceStore::row($db,'layouts',$org,$r['layout']);$zones=[];foreach(json_decode($layout['document_json'],true)['items'] as $seat)if($seat['kind']==='seat')$zones[$seat['zone']]=true;$visiblePrices=array_intersect_key($r['prices'],$zones);
        echo '<h3>Ticket prices</h3><p>'.CommerceProductionExperience::priceText($visiblePrices,CommerceStore::organization($db,$org)['currency']).'</p>';echo '<h3>Sales at creation</h3><p>'.($preview['initial_sales']==='open'?'On sale immediately':'Sales stay closed').' · Fee '.CommerceExperience::e(number_format($preview['fee_minor']/100,2)).' · Tax '.CommerceExperience::e(number_format($preview['tax_basis_points']/100,2)).'% · Discount '.CommerceExperience::e(number_format($preview['discount_minor']/100,2)).'</p>';if(!$preview['conflicts']&&hash_equals($preview['hash'],$r['preview']['hash'])){CommerceExperience::form('schedule_apply',['review_key'=>$key]);echo '<button>Create these '.count($preview['times']).' performances</button></form>';}else echo '<p>Resolve conflicts or configuration changes and create a fresh review. Nothing has been created.</p>';echo '<a data-commerce-drawer-link href="'.self::e(CommerceExperience::url(!empty($r['input']['drawer'])?'add_performance':'schedule',['production'=>$r['production']]+(!empty($r['input']['drawer'])?['draft'=>$key]:[]))).'">Back to schedule editor</a>';
    }
    public static function blocks(PDO $db,array $u,int $org):void
    {
        CommerceAccess::demand($db,$u,$org,'inventory');if(isset($_GET['review'])){self::allocationReview($db,$u,$org,(string)$_GET['review']);return;}$production=(int)($_GET['production']??0);echo '<h2>Block or release seats across shows</h2><p>Preview the full scope before applying. Any sold, held, missing or incompatible seat prevents the entire operation.</p><form method="get"><input type="hidden" name="tab" value="blocks">';self::productionSelect($db,$production);echo '<button>Choose production</button></form>';if(!$production)return;$performances=self::rows($db,'SELECT * FROM commerce_performances WHERE organization_id=? AND production_id=? ORDER BY starts_at',[$org,$production]);if(!$performances){echo '<p>No actual performances exist for this production.</p>';return;}
        CommerceExperience::form('allocation_review',['production'=>$production]);echo '<label>Performances to update<select name="scope"><option value="selected">Selected performances (one or more)</option><option value="range">Scheduled performances in a date range</option><option value="all">All performances in this production</option></select></label><fieldset><legend>Selected performances</legend>';foreach($performances as $p)echo '<label><input type="checkbox" name="performances[]" value="'.(int)$p['id'].'" '.((int)($_GET['id']??0)===(int)$p['id']?'checked':'').'>'.self::e(CommerceExperience::staffDate($p).' · '.CommerceExperience::staffStatus($p['schedule_status'])).'</label>';echo '</fieldset><div class="commerce-columns">';CommerceExperience::input('from','Range start (venue-local date)','date');CommerceExperience::input('to','Range end (venue-local date)','date');echo '</div><label>Action<select name="state"><option value="blocked">Block seats</option><option value="house">Create house holds</option><option value="complimentary">Allocate for complimentary issuance</option><option value="released">Release eligible blocks / house / complimentary allocations</option></select></label>';
        $mapId=(int)($_GET['id']??$performances[0]['id']);$mapPerformance=null;foreach($performances as $candidate)if((int)$candidate['id']===$mapId)$mapPerformance=$candidate;if(!$mapPerformance)$mapPerformance=$performances[0];$layout=CommerceStore::row($db,'layouts',$org,(int)$mapPerformance['layout_id']);echo '<h3>Visual seating reference</h3><p>Layout for '.self::e(CommerceExperience::staffDate($mapPerformance)).'. The seat list includes every layout in this production; review checks compatibility across the selected shows.</p>';CommerceExperience::allocationMap(json_decode($layout['document_json'],true));$seats=[];foreach($performances as $p)foreach(CommerceInventoryService::inventory($db,$org,(int)$p['id']) as $item){$s=json_decode($item['seat_json'],true);$seats[$item['seat_key']]=CommerceExperience::seatLabel($s);}uasort($seats,'strnatcasecmp');echo '<fieldset><legend>Seats (validated in every affected performance)</legend><p>If seating plans differ, select fewer performances and review each group separately.</p><div class="commerce-seat-list">';foreach($seats as $key=>$label)echo '<label><input type="checkbox" name="seats[]" value="'.self::e($key).'">'.self::e($label).'</label>';echo '</div></fieldset>';CommerceExperience::input('reason','Blocking or release reason','text','','required maxlength="500"');echo '<button>Preview affected performances & seats</button></form>';
    }
    private static function allocationReview(PDO $db,array $u,int $org,string $key):void
    {
        $r=self::review($org,$u,$key,'allocation');$preview=CommerceInventoryService::allocationPreview($db,$u,$org,$r['ids'],$r['seats'],$r['state'],$r['reason']);$currentScope=CommerceInventoryService::allocationScope($db,$u,$org,$r['scope']);$stale=$currentScope!==$r['ids']||!hash_equals($preview['hash'],$r['preview']['hash']);
        $labels=[];$units=[];foreach($r['ids'] as $id){$performance=CommerceStore::row($db,'performances',$org,$id);$units[$id]=$performance['seating_mode']==='general_admission'?'Ticket':'Seat';foreach(CommerceInventoryService::inventory($db,$org,$id) as $item)$labels[$id][$item['seat_key']]=CommerceExperience::seatLabel(json_decode($item['seat_json'],true));}
        $unit=count(array_unique($units))===1?(reset($units)==='Ticket'?'tickets':'seats'):'seats or tickets';
        echo '<h2>Review seat blocks and holds</h2><p>'.count($r['ids']).' performances · '.count($r['seats']).' '.$unit.' per performance · '.self::e(self::actionLabel($r['state'])).'</p><p>Reason: '.self::e($r['reason']).'</p>';
        if($stale)echo '<p role="alert">Availability or the selected performances changed. Review again; nothing has been applied.</p>';
        echo '<div class="commerce-table-scroll"><table><caption>Affected performances and seats</caption><thead><tr><th>Performance</th><th>Seat / ticket</th><th>Availability</th><th>Review</th></tr></thead><tbody>';
        foreach($preview['rows'] as $row){$label=$labels[$row['performance']][$row['seat']]??null;if(!$label)foreach($labels as $performanceLabels)if(isset($performanceLabels[$row['seat']])){$label=$performanceLabels[$row['seat']];break;}$label??='Not in this seating plan';$ticket=$units[$row['performance']]==='Ticket';
            $conflict=$row['conflict']===null?'Ready':match(true){$row['before']==='missing'=>'Not in this seating plan',str_starts_with($row['conflict'],'Current state ')=>'Cannot change: '.CommerceExperience::staffStatus($row['before']),default=>'This performance is not available for changes'};
            echo '<tr><td>'.self::e(CommerceExperience::staffDate($row['showtime']).' · '.$row['venue']).'</td><td>'.self::e($ticket?'General admission ticket':$label).'</td><td>'.self::e(CommerceExperience::staffStatus($row['before'])).'</td><td>'.self::e($conflict).'</td></tr>';
        }echo '</tbody></table></div>';
        if(!$stale&&!$preview['conflicts']){CommerceExperience::form('allocation_apply',['review_key'=>$key]);echo '<button>Apply to all '.count($preview['rows']).' '.$unit.'</button></form>';}else echo '<p role="alert">Nothing will be changed until all selected seats and performances are ready. Adjust your selection and review again.</p>';echo '<a href="'.self::e(CommerceExperience::url('blocks',['production'=>$r['scope']['production']])).'">Change performances or seats</a>';

    }
    private static function actionLabel(string $state):string
    {return match($state){'blocked'=>'Block seats','house'=>'Reserve for the house','complimentary'=>'Reserve complimentary tickets','released','available'=>'Release seats',default=>'Update seats'};}
    public static function showtimeControls(PDO $db,array $u,int $org,array $p,bool $compact=false):void
    {
        if(!$compact)echo '<details><summary>Performance schedule & cancellation</summary>';
        $draft=null;if(!empty($_GET['showtime_review'])){$draft=self::review($org,$u,(string)$_GET['showtime_review'],'showtime_ambiguity');if((int)$draft['performance']!==(int)$p['id'])throw new RuntimeException('This time review belongs to another performance.');}
        $input=$draft['input']??[];$history=self::rows($db,'SELECT 1 FROM commerce_orders WHERE organization_id=? AND performance_id=? LIMIT 1',[$org,$p['id']]);$saved=str_replace(' ','T',substr($p['starts_at'],0,16));
        if(!$p['starts_at_utc']){CommerceExperience::form('legacy_showtime',['id'=>$p['id']]);echo '<p>Saved performance: '.self::e(CommerceExperience::staffDate($p)).'</p><p>Confirm the venue’s local time before opening ticket sales. Existing tickets and orders stay unchanged.</p>';CommerceExperience::input('timezone','Venue timezone','text',$input['timezone']??CommercePerformancePolicy::venueTimezone($db,$org,(int)$p['layout_id']),'required');if($draft)self::occurrenceChoice();CommerceExperience::input('reason','Timezone review reason','text',$input['reason']??'','required maxlength="500"');echo '<button>Confirm venue time</button></form>';}
        elseif($p['starts_at_utc']>gmdate('Y-m-d H:i:s')&&!in_array($p['schedule_status'],['cancelled','completed'],true)){
            CommerceExperience::form('showtime_change',['id'=>$p['id'],'version'=>$input['version']??CommerceScheduleService::version($p)]);
            if($history){echo '<p>Saved performance: '.self::e(CommerceExperience::staffDate($p)).'</p><p>This performance has orders, so its date and time are fixed. To move it, cancel this performance and create another.</p><input type="hidden" name="starts" value="'.self::e($saved).'">';}
            else{CommerceExperience::input('starts','Performance date and time','datetime-local',$input['starts']??$saved,'required');if($draft)self::occurrenceChoice();}
            echo '<h4>Schedule and cancellation</h4><label>Performance status<select name="status">';foreach(['scheduled'=>'Scheduled','draft'=>'Draft','cancelled'=>'Cancel this performance'] as $key=>$label)echo '<option value="'.$key.'" '.(($input['status']??$p['schedule_status'])===$key?'selected':'').'>'.$label.'</option>';echo '</select></label><p>Cancelling closes sales and check-in, releases unpaid reservations and keeps existing tickets and orders. Refunds and customer contact must be handled separately. Pending payments must be resolved first.</p>';CommerceExperience::input('reason','Reason for change','text',$input['reason']??'','required maxlength="500"');echo '<label><input type="checkbox" name="acknowledge_paid" value="1" '.(!empty($input['acknowledge_paid'])?'checked':'').'> I will contact ticket holders and arrange any refunds separately if cancelling or changing to draft.</label><button>Save performance changes</button></form>';
        }else echo '<p>Past, completed and cancelled performances are kept for your records and cannot be rescheduled here.</p>';
        if(!$compact)echo '</details>';
    }
    private static function occurrenceChoice():void
    {echo '<label>This time occurs twice when clocks change. Which occurrence?<select name="offset" required><option value="">Choose occurrence</option><option value="earlier">First occurrence</option><option value="later">Second occurrence</option></select></label>';}
    private static function offset(int $minutes):string{return($minutes<0?'-':'+').sprintf('%02d:%02d',intdiv(abs($minutes),60),abs($minutes)%60);}
}
